/* Only the 700 face is loaded: blocks ask for font-semibold (600), which then renders in 700,
   the closest match to the original's heavy 600. */
@import "@fontsource/encode-sans-expanded/700.css";
@import "@fontsource-variable/rubik";

/* Light (faithful): warm paper white, deep indigo ink for headings, plain grey body copy,
   an electric violet brand, lavender for quiet text on violet, lemon yellow for the loud bits
   (highlight), and a deep indigo band for the footer (secondary). */
:root {
  --background: rgb(255 254 252);
  --foreground: rgb(35 15 102);
  --card: rgb(255 254 252);
  --card-foreground: rgb(35 15 102);
  --popover: rgb(71 37 184);
  --popover-foreground: rgb(255 254 252);
  --primary: rgb(71 37 184);
  --primary-foreground: rgb(255 254 252);
  --secondary: rgb(35 15 102);
  --secondary-foreground: rgb(255 254 252);
  --muted: rgb(224 224 224);
  --muted-foreground: rgb(102 102 102);
  --accent: rgb(179 156 255);
  --accent-foreground: rgb(35 15 102);
  --destructive: rgb(200 40 50);
  --destructive-foreground: rgb(255 254 252);
  --border: rgb(224 224 224);
  --input: rgb(224 224 224);
  --ring: rgb(71 37 184);
  --highlight: rgb(255 234 0);
  --highlight-foreground: rgb(35 15 102);
  --glow: rgb(96 70 210);
  --chart-1: rgb(71 37 184);
  --chart-2: rgb(179 156 255);
  --chart-3: rgb(255 234 0);
  --chart-4: rgb(35 15 102);
  --chart-5: rgb(102 102 102);
  --sidebar: rgb(255 254 252);
  --sidebar-foreground: rgb(35 15 102);
  --sidebar-primary: rgb(71 37 184);
  --sidebar-primary-foreground: rgb(255 254 252);
  --sidebar-accent: rgb(179 156 255);
  --sidebar-accent-foreground: rgb(35 15 102);
  --sidebar-border: rgb(224 224 224);
  --sidebar-ring: rgb(71 37 184);

  --typeface-body: "Rubik Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Encode Sans Expanded", "Rubik Variable", ui-sans-serif, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0rem;
  --page-width: 120rem;
  /* 60px at 1440, ~19px at 390: the original's fluid side margin */
  --page-gutter: clamp(1rem, 0.214rem + 3.93vw, 3.75rem);
  /* 84px on phones up to 120px on wide screens */
  --section-y: clamp(5.25rem, 4.6rem + 3.21vw, 7.5rem);
}

/* Dark (sibling): the deep indigo becomes the page, near-black indigo for the footer band,
   lavender-white ink, a brighter violet brand, the same lavender and lemon yellow. */
.dark {
  --background: rgb(24 12 66);
  --foreground: rgb(240 236 255);
  --card: rgb(32 18 84);
  --card-foreground: rgb(240 236 255);
  --popover: rgb(92 60 220);
  --popover-foreground: rgb(255 254 252);
  --primary: rgb(92 60 220);
  --primary-foreground: rgb(255 254 252);
  --secondary: rgb(12 6 38);
  --secondary-foreground: rgb(255 254 252);
  --muted: rgb(48 34 104);
  --muted-foreground: rgb(190 182 222);
  --accent: rgb(179 156 255);
  --accent-foreground: rgb(24 12 66);
  --destructive: rgb(240 90 90);
  --destructive-foreground: rgb(255 254 252);
  --border: rgb(240 236 255 / 14%);
  --input: rgb(240 236 255 / 20%);
  --ring: rgb(179 156 255);
  --highlight: rgb(255 234 0);
  --highlight-foreground: rgb(24 12 66);
  --glow: rgb(120 92 240);
  --chart-1: rgb(179 156 255);
  --chart-2: rgb(92 60 220);
  --chart-3: rgb(255 234 0);
  --chart-4: rgb(240 236 255);
  --chart-5: rgb(190 182 222);
  --sidebar: rgb(32 18 84);
  --sidebar-foreground: rgb(240 236 255);
  --sidebar-primary: rgb(92 60 220);
  --sidebar-primary-foreground: rgb(255 254 252);
  --sidebar-accent: rgb(48 34 104);
  --sidebar-accent-foreground: rgb(240 236 255);
  --sidebar-border: rgb(240 236 255 / 14%);
  --sidebar-ring: rgb(179 156 255);
}
